# Generated by `cargo xtask formula` in michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.14.0/acs-0.14.0-aarch64-apple-darwin.tar.gz"
      sha256 "1ee2fbac0b1b5c7edbe79ff7e41ff75c6bc822948476efeb64c7cd54cab52638"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.14.0/acs-0.14.0-x86_64-apple-darwin.tar.gz"
      sha256 "f4aca92c80330fd5d47265e78beeb8e1124f5ed05c040fc6c4f6c822cb372832"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.14.0/acs-0.14.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "93b79bdc117af152a8b15259abccc2dd16d9cf282e2fa4c97469354f2d3f064b"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.14.0/acs-0.14.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "afb018ecdaac6fa934c1d0fa4112b4e08df1bdce299f0444fdee9cb5d15e06b2"
    end
  end

  def install
    bin.install "acs"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
  end
end
